def test_native_prepared_invalid_live_payload_preserves_particles_and_gas(
    device, failure
):
    """Invalid live state gates the source before any primary writer."""
    import warp as wp

    from particula.gpu.kernels import nucleation as module

    p, g, config, kwargs = setup(device)
    prepared = module._prepare_nucleation_step_gpu(p, g, config, 1.0, **kwargs)
    if failure == "density":
        wp.copy(p.volume, wp.array([1e-309], dtype=wp.float64, device=device))
    elif failure == "partitioning":
        wp.copy(
            g.partitioning,
            wp.array([[0, 0, 1, 0]], dtype=wp.int32, device=device),
        )
    elif failure == "gas":
        wp.copy(
            g.concentration,
            wp.array(
                [[7.0, -1.0, 100.0, 9.0]], dtype=wp.float64, device=device
            ),
        )
    else:
        wp.copy(
            g.concentration,
            wp.array(
                [[7.0, 100.0, 50.0, 9.0]], dtype=wp.float64, device=device
            ),
        )
    arrays = [p.masses, p.concentration, p.charge, p.volume, g.concentration]
    before = [array.numpy().copy() for array in arrays]
    module._enqueue_prepared_nucleation_call(prepared)
    with pytest.raises(ValueError):
        module._observe_prepared_nucleation_call(prepared)
    for array, expected in zip(arrays, before, strict=True):
        np.testing.assert_array_equal(array.numpy(), expected)

def test_public_nucleation_step_gates_are_exact_write_free(
    device, kind
) -> None:
    """Zero-demand public gates preserve particles and gas byte-for-byte."""
    wp = _warp()
    api = _api()
    particles, gas = _state(device)
    scratch, finalized, diagnostics, exhaustion = _sidecars(
        api, device, 1, 3, 2
    )
    kwargs = {"time_step": 1.0, "config": _config(api)}
    if kind == "zero_time":
        kwargs["time_step"] = 0.0
    elif kind == "zero_coefficient":
        kwargs["config"] = _config(api, coefficient=0.0)
    else:
        kwargs["config"] = _config(
            api, saturation_lower=2.0, saturation_upper=3.0
        )
        kwargs["saturation"] = wp.ones((1, 2), dtype=wp.float64, device=device)
    before = _snapshot(particles, gas)
    api.nucleation_step_gpu(
        particles,
        gas,
        kwargs["config"],
        kwargs["time_step"],
        scratch=scratch,
        finalized_demand=finalized,
        diagnostics=diagnostics,
        exhaustion_controls=api.NucleationExhaustionControls(False, False),
        exhaustion_buffers=exhaustion,
        temperature=300.0,
        **(
            {"saturation": kwargs["saturation"]}
            if "saturation" in kwargs
            else {}
        ),
    )
    wp.synchronize_device(device)
    _assert_unchanged(before)

def test_stage_nucleation_slots_accepts_int32_maximum_event_count():
    """The inclusive int32 event-count boundary is accepted independently."""
    _, _, _, finalized, _ = _stage_slots(
        [float(np.iinfo(np.int32).max)], np.array([[False]])
    )
    np.testing.assert_array_equal(
        finalized.accepted_counts.numpy(), [np.iinfo(np.int32).max]
    )

def test_scalar_zero_config_gates_before_temperature_interval(
    temperature, changes
):
    """Valid zero rate inputs short-circuit configured scalar temperature bounds."""
    particles, gas = _state()
    result = _preflight_nucleation(
        particles, gas, _config(**changes), 1.0, temperature=temperature
    )
    assert result.gate_reason in ("zero_coefficient", "zero_survival")
